/** Kapitel der Geschichte (seit 0.19.0: „Lyra, Kael und Fenrir – Das Geheimnis der Waldhüter“, Band 1, Kapitel 1–7 von 34;
 *  Text: „HABIVALE/Ausgang/Märchenbuch Band 1“). Jedes Kapitel ist ein Teil = ein Abend: je Tag geht höchstens ein neues Kapitel auf
 *  (`src/logic/story.ts`). Neue Kapitel hinten anhängen (Regel `start`), die Ids `s<Kapitel>-1` bleiben dann gleich. */
export interface Chapter {
  title: string;
  rule: Rule;
  /** Teile → Absätze */
  parts: string[][];
}

